Here the distance search and the path counting are kept together, but the priority queue is replaced with the simple `O(n^2)` version of Dijkstra. On each round, the code scans all nodes to find the unused node with the smallest distance.

A dry run for two equal routes is straightforward. If node `1` reaches the destination in time `5`, and node `2` also reaches it in time `5`, the destination count changes from `1` to `2`.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution{
public:
    int countPaths(int n, vector<vector<int>> &roads) {
        const long long INF = 4'000'000'000'000'000'000LL;
        const int MOD = 1'000'000'007;

        vector<vector<pair<int, int>>> graph(n);
        for (const vector<int>& road : roads) {
            int u = road[0];
            int v = road[1];
            int time = road[2];
            graph[u].push_back({v, time});
            graph[v].push_back({u, time});
        }

        vector<long long> dist(n, INF);
        vector<int> ways(n, 0);
        vector<bool> used(n, false);
        dist[0] = 0;
        ways[0] = 1;

        for (int step = 0; step < n; step++) {
            int node = -1;

            for (int i = 0; i < n; i++) {
                if (!used[i] && (node == -1 || dist[i] < dist[node])) {
                    node = i;
                }
            }

            if (node == -1 || dist[node] == INF) {
                break;
            }

            used[node] = true;

            for (auto [neighbor, time] : graph[node]) {
                long long nextDistance = dist[node] + time;

                if (nextDistance < dist[neighbor]) {
                    dist[neighbor] = nextDistance;
                    ways[neighbor] = ways[node];
                } else if (nextDistance == dist[neighbor]) {
                    ways[neighbor] = (ways[neighbor] + ways[node]) % MOD;
                }
            }
        }

        return ways[n - 1];
    }
};
```

The graph is guaranteed to be connected, but the `INF` check still makes the loop safe for an unreachable input. This version avoids heap code, though it is slower for large sparse graphs.

Time complexity: `O(n^2 + m)`.
Space complexity: `O(n + m)`.

This uses Floyd-Warshall to find the shortest distance from node `0` to every node. After that, the nodes are ordered by their distance, and the code counts only edges that continue along a shortest route.

The first part is slower than heap-based Dijkstra, but it gives a different way to handle the distance table. Positive road times are important because they make the shortest-route edges move from a smaller distance to a larger one.

```go
package main

import "sort"

func countPaths(n int, roads [][]int) int {
	const MOD int64 = 1_000_000_007
	const INF int64 = 1 << 60

	dist := make([][]int64, n)
	for i := 0; i < n; i++ {
		dist[i] = make([]int64, n)
		for j := 0; j < n; j++ {
			dist[i][j] = INF
		}
		dist[i][i] = 0
	}

	for _, road := range roads {
		u, v, time := road[0], road[1], int64(road[2])
		dist[u][v] = time
		dist[v][u] = time
	}

	for middle := 0; middle < n; middle++ {
		for from := 0; from < n; from++ {
			if dist[from][middle] == INF {
				continue
			}
			for to := 0; to < n; to++ {
				through := dist[from][middle] + dist[middle][to]
				if through < dist[from][to] {
					dist[from][to] = through
				}
			}
		}
	}

	order := make([]int, n)
	for i := 0; i < n; i++ {
		order[i] = i
	}
	sort.Slice(order, func(i, j int) bool {
		return dist[0][order[i]] < dist[0][order[j]]
	})

	ways := make([]int64, n)
	ways[0] = 1

	for _, from := range order {
		for _, road := range roads {
			u, v, time := road[0], road[1], int64(road[2])

			if u == from && dist[0][u]+time == dist[0][v] {
				ways[v] = (ways[v] + ways[u]) % MOD
			}
			if v == from && dist[0][v]+time == dist[0][u] {
				ways[u] = (ways[u] + ways[v]) % MOD
			}
		}
	}

	return int(ways[n-1])
}
```

A single node still has one way to reach itself, so `ways[0]` starts at `1`. The code also uses `int64` for distances to avoid overflow when many large road times are added.

Time complexity: `O(n^3 + nm + n log n)`, where `m` is the number of roads.
Space complexity: `O(n^2 + m)`.

Kept the shortest distance and the number of shortest routes in separate arrays. The priority queue processes the smallest distance first, which is what makes the greedy choice work for positive road times.

When a new route is shorter, its count becomes the count of the previous node. When it ties the current best distance, the count is added instead.

```java
import java.util.*;

class Solution {
    public int countPaths(int n, List<List<Integer>> roads) {
        final int MOD = 1_000_000_007;
        List<List<int[]>> graph = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (List<Integer> road : roads) {
            int from = road.get(0);
            int to = road.get(1);
            int time = road.get(2);
            graph.get(from).add(new int[]{to, time});
            graph.get(to).add(new int[]{from, time});
        }

        long[] distance = new long[n];
        Arrays.fill(distance, Long.MAX_VALUE);
        int[] ways = new int[n];
        distance[0] = 0;
        ways[0] = 1;

        PriorityQueue<long[]> queue = new PriorityQueue<>(
            Comparator.comparingLong(item -> item[0])
        );
        queue.offer(new long[]{0, 0});

        while (!queue.isEmpty()) {
            long[] current = queue.poll();
            long currentTime = current[0];
            int node = (int) current[1];

            if (currentTime > distance[node]) {
                continue;
            }

            for (int[] edge : graph.get(node)) {
                int next = edge[0];
                long newTime = currentTime + edge[1];

                if (newTime < distance[next]) {
                    distance[next] = newTime;
                    ways[next] = ways[node];
                    queue.offer(new long[]{newTime, next});
                } else if (newTime == distance[next]) {
                    ways[next] = (ways[next] + ways[node]) % MOD;
                }
            }
        }

        return ways[n - 1];
    }
}
```

The `long` distance array matters because a path can contain many roads with large times. The returned count is an `int` because every addition is reduced by the modulo.

Time complexity: `O((n + m) log n)`.
Space complexity: `O(n + m)`.

This version separates the two jobs. First, Dijkstra finds the shortest distance to every node. Then the nodes are sorted by distance, and a small dynamic programming pass counts only edges that belong to a shortest route.

The second pass is easy to check: an edge from `u` to `v` can carry shortest paths only when `dist[u] + time == dist[v]`.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution{
public:
    int countPaths(int n, vector<vector<int>> &roads) {
        const int MOD = 1'000'000'007;
        vector<vector<pair<int, int>>> graph(n);

        for (const vector<int>& road : roads) {
            int u = road[0];
            int v = road[1];
            int time = road[2];
            graph[u].push_back({v, time});
            graph[v].push_back({u, time});
        }

        vector<long long> dist(n, LLONG_MAX);
        priority_queue<pair<long long, int>,
                       vector<pair<long long, int>>,
                       greater<pair<long long, int>>> pq;

        dist[0] = 0;
        pq.push({0, 0});

        while (!pq.empty()) {
            auto [currentDistance, node] = pq.top();
            pq.pop();

            if (currentDistance != dist[node]) {
                continue;
            }

            for (auto [neighbor, time] : graph[node]) {
                long long nextDistance = currentDistance + time;
                if (nextDistance < dist[neighbor]) {
                    dist[neighbor] = nextDistance;
                    pq.push({nextDistance, neighbor});
                }
            }
        }

        vector<int> order(n);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) {
            return dist[a] < dist[b];
        });

        vector<int> ways(n, 0);
        ways[0] = 1;

        for (int node : order) {
            for (auto [neighbor, time] : graph[node]) {
                if (dist[node] + time == dist[neighbor]) {
                    ways[neighbor] = (ways[neighbor] + ways[node]) % MOD;
                }
            }
        }

        return ways[n - 1];
    }
};
```

Because every road time is positive, a shortest-path edge always goes from a smaller distance to a larger distance. That is why sorting by distance gives a safe order for the counting pass. The input `roads` is not changed.

Time complexity: `O((n + m) log n + n log n)`.
Space complexity: `O(n + m)`.
